class Solution:
    def calculateTax(self, brackets: List[List[int]], income: float) -> float:
        tax, prev = 0.0, 0
        for u, p in brackets:
            if income <= u:
                tax += (income - prev) * p / 100
                break
            tax += (u - prev) * p / 100
            prev = u
        return tax

c.cpp:
class Solution {
public:
    double calculateTax(vector<vector<int>>& brackets, int income) {
        double tax = 0; int prev = 0;
        for (auto& b : brackets) {
            int u = b[0], p = b[1];
            if (income <= u) { tax += (income - prev) * p / 100.0; break; }
            tax += (u - prev) * p / 100.0;
            prev = u;
        }
        return tax;
    }
};

